/// @title IMetricOmmPoolActions
/// @notice Interface for user actions: liquidity provision, removal, and swaps
interface IMetricOmmPoolActions {
  // ============ Errors ============

  /// @notice Thrown when liquidity amount is below minimum
  error MinimalLiquidity(uint104 afterOperation, uint104 minimalRequired);

  /// @notice Thrown when requested liquidity exceeds available
  error InsufficientLiquidity(uint104 requested, uint104 available);

  /// @notice Thrown when tick range is invalid
  error InvalidTickRange();

  /// @notice Thrown when position does not exist
  error PositionNotFound();

  /// @notice Thrown when drift limit is exceeded
  error DriftLimitExceeded();

  /// @notice Thrown when distance is too negative
  error DistanceTooNegative();

  /// @notice Thrown when amount is insufficient
  error InsufficientAmount();

  /// @notice Thrown when pool is locked (reentrancy guard)
  error PoolLocked();

  /// @notice Thrown when callback doesn't pay enough tokens
  error IncorrectDelta();

  /// @notice Thrown when amount0 delta exceeds the specified limit
  /// @param actual The actual token0 delta (positive = pay, negative = receive)
  /// @param specified The user's specified limit
  error Amount0BelowSpecified(int128 actual, int128 specified);

  /// @notice Thrown when amount1 delta exceeds the specified limit
  /// @param actual The actual token1 delta (positive = pay, negative = receive)
  /// @param specified The user's specified limit
  error Amount1BelowSpecified(int128 actual, int128 specified);

  /// @notice Thrown when swap amount is zero
  error InvalidAmount();

  /// @notice  Thrown when price provider bid price is greater than ask
  error BidGreaterThanAsk();

  /// @notice Thrown when price provider bid price is zero
  error BidIsZero();

  /// @notice ERC-7751 Wrapped error for external call failures
  /// @param target The address of the contract that was called
  /// @param selector The function selector that was called
  /// @param reason The revert reason from the failed call
  /// @param details Additional context about the error
  error WrappedError(address target, bytes4 selector, bytes reason, bytes details);

  /// @notice Thrown when simulating a swap to return the result via revert
  error SimulateSwap(int128 amount0Delta, int128 amount1Delta);

  /// @notice Thrown when bin index is out of valid range
  error InvalidBinIndex(int16 bin);

  // ============ Type Definitions for Granular Liquidity ============

  /// @notice Represents a liquidity change for a single bin
  /// @param bin The bin index to modify
  /// @param deltaShares Positive = add shares, Negative = remove shares
  struct LiquidityDelta {
    int16 bin;
    int104 deltaShares;
  }

  // ============ Events ============

  /// @notice Emitted when a swap is executed
  /// @param sender The address executing the swap
  /// @param recipient The address receiving the output tokens
  /// @param exactInput Indicates if the swap is for exact input (true) or exact output (false)
  /// @param amount0Delta Change in token0 balance (positive = pool receives, negative = pool sends)
  /// @param amount1Delta Change in token1 balance (positive = pool receives, negative = pool sends)
  /// @param newTick The tick after the swap
  /// @param newPositionInBin The position within the bin after the swap
  event Swap(
    address sender,
    address recipient,
    bool exactInput,
    int128 amount0Delta,
    int128 amount1Delta,
    int16 newTick,
    uint104 newPositionInBin
  );

  /// @notice Emitted when liquidity is modified granularly via modifyLiquidity
  /// @param provider The address modifying liquidity
  /// @param salt The salt identifying the position
  /// @param amount0Delta Net token0 change (positive = deposited, negative = withdrawn)
  /// @param amount1Delta Net token1 change (positive = deposited, negative = withdrawn)
  /// @param bins Array of bin indices that were modified
  /// @param deltaShares Array of share deltas corresponding to each bin
  event LiquidityModified(
    address indexed provider,
    uint80 indexed salt,
    int128 amount0Delta,
    int128 amount1Delta,
    int16[] bins,
    int104[] deltaShares
  );

  // ============ Liquidity Functions ============

  /// @notice Add or remove liquidity from specific bins granularly
  /// @dev Allows precise control over liquidity in individual bins
  /// @param salt Unique identifier for the position (80 bits)
  /// @param deltas Array of bin/shares changes to apply
  /// @param specAmount0 Slippage protection for token0:
  ///        - Maximum amount willing to deposit/minimum to withdraw
  /// @param specAmount1 Slippage protection for token1 (same semantics as specAmount0)
  /// @return amount0Delta Net token0 change (positive = user deposits, negative = user withdraws)
  /// @return amount1Delta Net token1 change (positive = user deposits, negative = user withdraws)
  function modifyLiquidity(uint80 salt, LiquidityDelta[] calldata deltas, int128 specAmount0, int128 specAmount1)
    external
    returns (int128 amount0Delta, int128 amount1Delta);

  // ============ Swap Functions ============

  /// @notice Execute a swap in the pool
  /// @param recipient The address that will receive the output tokens
  /// @param zeroForOne The direction of the swap (true = token0 -> token1, false = token1 -> token0)
  /// @param amountSpecified The amount for the swap:
  ///        - Positive: exact input amount
  ///        - Negative: exact output amount
  /// @param priceLimitX64 The price limit in X64 format (Q64.64 fixed point)
  /// @param data Additional data (unused, for future compatibility)
  /// @return amount0Delta The change in token0 balance (positive = pool receives, negative = pool sends)
  /// @return amount1Delta The change in token1 balance (positive = pool receives, negative = pool sends)
  function swap(address recipient, bool zeroForOne, int128 amountSpecified, uint128 priceLimitX64, bytes calldata data)
    external
    returns (int128 amount0Delta, int128 amount1Delta);

  /// @notice Simulate a swap and revert with the result
  /// @param zeroForOne The direction of the swap (true = token0 -> token1, false = token1 -> token0)
  /// @param amountSpecified The amount for the swap
  /// @param priceLimitX64 The price limit in X64 format
  /// @param bidPriceX64 The bid price in X64 format
  /// @param askPriceX64 The ask price in X64 format
  /// @return amount0Delta The change in token0 balance
  /// @return amount1Delta The change in token1 balance
  function simulateSwapAndRevert(
    bool zeroForOne,
    int128 amountSpecified,
    uint128 priceLimitX64,
    uint128 bidPriceX64,
    uint128 askPriceX64
  ) external returns (int128 amount0Delta, int128 amount1Delta);
}

