        return uint104((currBinPos * (availableToken1 - tradedAmount1)) / availableToken1);
      } else {
        return uint104(Math.ceilDiv(currBinPos * (availableToken1 - tradedAmount1), availableToken1));
      }
    }
  }

  /**
   * @notice Calculate output token1 amount from position movement
   * @param availableToken1 Available token1 in bin. Assumes <= type(uint104).max.
   * @param currBinPos Start position (uint104). Assumes > 0.
   * @param finalBinPos End position (uint104). Assumes <= currBinPos.
   * @return outToken1 Amount of token1 to output (rounds down). Result <= type(uint104).max.
   */
  function calculateOutputToken1FromBinPosition(uint256 availableToken1, uint104 currBinPos, uint104 finalBinPos)
    internal
    pure
    returns (uint256 outToken1)
  {
    unchecked {
      // Product ≤ 2^104 × 2^104 = 2^208. Quotient ≤ availableToken1 ≤ type(uint104).max.
      outToken1 = (availableToken1 * uint256(currBinPos - finalBinPos)) / currBinPos;
    }
  }

  /**
   * @notice Calculate output token0 amount from position movement
   * @param availableToken0 Available token0 in bin. Assumes <= type(uint104).max.
   * @param currBinPos Start position (uint104). Assumes < type(uint104).max.
   * @param finalBinPos End position (uint104). Assumes >= currBinPos.
   * @return outToken0 Amount of token0 to output (rounds down). Result <= type(uint104).max.
   */
  function calculateOutputToken0FromBinPosition(uint256 availableToken0, uint104 currBinPos, uint104 finalBinPos)
    internal
    pure
    returns (uint256 outToken0)
  {
    unchecked {
      // Product ≤ 2^104 × 2^104 = 2^208. Quotient ≤ availableToken0 ≤ type(uint104).max.
