    }
  }

  // ============ Token Conversion Helpers ============

  /**
   * @notice Calculate required token1 input for given token0 amount (both in the same internal decimals)
   * @param token0Amount Assumes <= type(uint104).max.
   * @param avgPriceX64 Assumes <= type(uint128).max (Q64.64 format) and > 0.
   * @return requiredToken1 Token1 input in internal decimals. Result <= type(uint128).max.
   */
  function calculateRequiredToken1(uint256 token0Amount, uint256 avgPriceX64)
    internal
    pure
    returns (uint256 requiredToken1)
  {
    // Product ≤ (2^104 + 1) × 2^128 ≈ 2^232 < 2^256.
    requiredToken1 = Math.ceilDiv((token0Amount + 1) * avgPriceX64, (1 << 64));
  }

  /**
   * @notice Calculate required token0 input for given token1 amount (both in the same internal decimals)
   * @param token1Amount Assumes <= type(uint104).max.
   * @param avgPriceX64 Assumes <= type(uint128).max (Q64.64 format) and > 0.
   * @return requiredToken0 Token0 input in internal decimals. Result <= type(uint128).max.
   */
  function calculateRequiredToken0(uint256 token1Amount, uint256 avgPriceX64)
    internal
    pure
    returns (uint256 requiredToken0)
  {
    // Shift ≤ (2^104 + 1) << 64 ≈ 2^168 < 2^256.
    requiredToken0 = Math.ceilDiv((token1Amount + 1) << 64, avgPriceX64);
  }

  // ============ Analytical Target Position Helpers ============

  /**
   * @notice Compute target bin position using analytical closed-form solution for buying token0
   * @dev Solves the quadratic equation: A×d + B×d² = target
   *      d = 2 * target / (A + sqrt(A² + 4B×target)) = 2Q / (1 + sqrt(1 + 4rQ))
   *      where:
   *        r = B/A and Q = target / A
   *        A = T0 × Pc / [(M-c) × 2^64] × (1e6 + fee) / 1e6
   *        B = ΔP / (2M × Pc) × A
   * @param currBinPos Current position in bin. Assumes <= type(uint104).max.
   * @param maxFinalBinPos Maximum achievable final position. Assumes currBinPos < maxFinalBinPos <= type(uint104).max.
   * @param inputAmount Amount of token1 input to spend. Assumes <= type(uint128).max.
   * @param token0Balance Available token0 in bin. Assumes <= type(uint104).max.
   * @param lowerPriceX64 Lower price bound of bin. Assumes <= type(uint128).max.
   * @param upperPriceX64 Upper price bound of bin. Assumes lowerPriceX64 < upperPriceX64 <= type(uint128).max.
   * @param feeE6 Constant fee (E6 units). Assumes <= type(uint24).max.
   * @return targetPos Computed target position. Result satisfies currBinPos < targetPos <= maxFinalBinPos.
   */
  function computeAnalyticalTargetPosForBuyToken0(
    uint104 currBinPos,
    uint104 maxFinalBinPos,
    uint256 inputAmount,
    uint256 token0Balance,
    uint256 lowerPriceX64,
    uint256 upperPriceX64,
    uint256 feeE6
  ) internal pure returns (uint104 targetPos) {
    uint256 M = type(uint104).max;
    uint256 c = currBinPos;
    uint256 T0 = token0Balance;
    uint256 Mc = M - c;

    uint256 deltaPX64 = upperPriceX64 - lowerPriceX64;
    // Price at current position
    uint256 PcX64 = lowerPriceX64 + (deltaPX64 * c) / M;

    uint256 d = 0;
    if (T0 > 0 && PcX64 > 0 && Mc > 0) {
      uint256 A_X128 = Math.mulDiv(T0 * (1e6 + feeE6), PcX64 << 64, Mc * 1e6);

      if (A_X128 > 0) {
        uint256 Q_X128 = Math.mulDiv(inputAmount << 128, 1 << 128, A_X128);

        // Apply quadratic correction
        // Exact solution: d = 2Q / (1 + sqrt(1 + 4rQ))
        // where r = B/A = ΔP / (M × Pc)
        if (deltaPX64 > 0) {
          // rQ_X128 = ΔP × Q_X128 / (M × Pc) = rQ × 2^128
          uint256 rQ_X128 = Math.mulDiv(deltaPX64, Q_X128, 2 * M * PcX64);

          // Exact quadratic solution: d = 2Q / (1 + sqrt(1 + 4rQ))
          uint256 sqrtArgX128 = (1 << 128) + 4 * rQ_X128;
          uint256 sqrtValX64 = Math.sqrt(sqrtArgX128);
          d = (2 * Q_X128) / ((1 << 128) + (sqrtValX64 << 64));
        } else {
          // Linear case (can happen for very small swaps):
          d = Q_X128 >> 128;
        }
      }
    }

    if (d == 0 && inputAmount > 0) d = 1;

    if (d > Mc) d = Mc;
    targetPos = (c + d > maxFinalBinPos) ? maxFinalBinPos : uint104(c + d);
    if (targetPos <= currBinPos && currBinPos < maxFinalBinPos) targetPos = currBinPos + 1;
  }

  /**
   * @notice Compute target bin position using analytical closed-form solution for selling token0
   * @dev Solves the quadratic equation: A×d + B×d² = target
   *      d = 2 * target / (A + sqrt(A² + 4B×target)) = 2Q / (1 + sqrt(1 + 4rQ))
   *      where:
   *        A = T1 × 2^64 / [c × Pc] × (1 + fee/1e6)
   *        B = ΔP / (2M × Pc) × A
   *        r = B/A = ΔP / (2M × Pc)
   * @param currBinPos Current position in bin. Assumes <= type(uint104).max.
   * @param minFinalBinPos Minimum achievable final position. Assumes minFinalBinPos < currBinPos.
   * @param inputAmount Amount of token0 input to spend. Assumes <= type(uint128).max.
   * @param token1Balance Available token1 in bin. Assumes <= type(uint104).max.
   * @param lowerPriceX64 Lower price bound of bin. Assumes <= type(uint128).max.
   * @param upperPriceX64 Upper price bound of bin. Assumes lowerPriceX64 < upperPriceX64 <= type(uint128).max.
   * @param feeE6 Constant fee (E6 units). Assumes <= type(uint24).max.
   * @return targetPos Computed target position. Result satisfies minFinalBinPos <= targetPos < currBinPos.
   */
  function computeAnalyticalTargetPosForSellToken0(
    uint104 currBinPos,
    uint104 minFinalBinPos,
    uint256 inputAmount,
    uint256 token1Balance,
    uint256 lowerPriceX64,
    uint256 upperPriceX64,
    uint256 feeE6
  ) internal pure returns (uint104 targetPos) {
    uint256 M = type(uint104).max;
    uint256 c = currBinPos;
    uint256 T1 = token1Balance;

    // Price gradient (constant fee, so no fee gradient)
    uint256 deltaPX64 = upperPriceX64 > lowerPriceX64 ? (upperPriceX64 - lowerPriceX64) : 0;

    // Price at current position
    uint256 PcX64 = lowerPriceX64 + (deltaPX64 * c) / M;

    uint256 d = 0;

    if (c > 0 && PcX64 > 0 && T1 > 0) {
      uint256 A_X128 = Math.mulDiv(T1 * (1e6 + feeE6), 1 << 192, PcX64 * c * 1e6);

      if (A_X128 > 0) {
        uint256 Q_X128 = Math.mulDiv(inputAmount << 128, 1 << 128, A_X128);

        // Apply quadratic correction for price gradient
        // Exact solution: d = 2Q / (1 + sqrt(1 + 4rQ))
        // where r = B/A = ΔP / (2M × Pc)
        if (deltaPX64 > 0) {
          uint256 rQ_X128 = Math.mulDiv(deltaPX64, Q_X128, 2 * M * PcX64);

          // Exact quadratic solution: d = 2Q / (1 + sqrt(1 + 4rQ))
          if (rQ_X128 > 0) {
            uint256 sqrtArg = (1 << 128) + 4 * rQ_X128;
            uint256 sqrtVal = Math.sqrt(sqrtArg);
            d = (2 * Q_X128) / ((1 << 128) + (sqrtVal << 64));
          } else {
            // rQ_X128 is 0, use linear approximation
            d = Q_X128 >> 128;
          }
        } else {
          // Linear case (can happen for very small swaps):
          d = Q_X128 >> 128;
        }
      }
    }

    if (d == 0 && inputAmount > 0) d = 1;

    if (d > c) {
      targetPos = minFinalBinPos;
    } else {
      targetPos = (c - d < minFinalBinPos) ? minFinalBinPos : uint104(c - d);
    }

    if (targetPos < minFinalBinPos) targetPos = minFinalBinPos;
    if (targetPos >= currBinPos && currBinPos > 0) targetPos = currBinPos - 1;
  }

  // ============ Swap In Bin Functions ============

  /**
   * @notice Calculate swap amounts for a single bin iteration (token1 → token0, exact output)
   * @param binState Current bin state
