      // Both uint104: sum ≤ 2 × 2^104, avg ≤ type(uint104).max
      uint104 xAvg = uint104(Math.ceilDiv(uint256(currBinPos) + uint256(finalBinPos), 2));
      uint256 avgPriceX64 = calculatePriceAtBinPosition(lowerPrice, upperPrice, xAvg, Math.Rounding.Ceil);

      uint256 amountIn = calculateRequiredToken1(amountOut, avgPriceX64);

      uint256 feeAmount = Math.ceilDiv(amountIn * currBinAddBuyFeeE6, 1e6);
      amountIn += feeAmount;
      uint256 protocolFeeAmount = (feeAmount * performanceFeeE6) / 1e6;

      binState.token0BalanceScaled -= amountOut.toUint104();
      binState.token1BalanceScaled = (uint256(binState.token1BalanceScaled) + amountIn - protocolFeeAmount).toUint104();

      state.amountSpecifiedRemainingScaled -= amountOut;
      state.amountCalculatedScaled += amountIn;
      state.protocolFeeAmount += protocolFeeAmount;

      return (finalBinPos);
    }
  }

