        out1 = calculateOutputToken1FromBinPosition(binState.token1BalanceScaled, currBinPos, targetPos);

        avgPos = uint104((uint256(currBinPos) + uint256(targetPos)) / 2);
        avgPrice = calculatePriceAtBinPosition(lowerPrice, upperPrice, avgPos, Math.Rounding.Floor);
        in0WithoutFee = calculateRequiredToken0(out1, avgPrice);
        totalIn0 = Math.ceilDiv(in0WithoutFee * (1e6 + currBinTotalSellFeeE6), 1e6);

        if (totalIn0 < state.amountSpecifiedRemainingScaled && targetPos > minFinalBinPos) {
          if (totalIn0 == 0) totalIn0 = 1;

          uint256 delta = currBinPos - targetPos;
          // remaining > totalIn0 ⇒ scaledDelta > delta, may exceed type(uint104).max → keep uint256
          uint256 scaledDelta = Math.ceilDiv(delta * state.amountSpecifiedRemainingScaled, totalIn0);
          if (scaledDelta == 0) scaledDelta = 1;
          targetPos = currBinPos > scaledDelta ? currBinPos - uint104(scaledDelta) : 0;
          if (targetPos < minFinalBinPos) {
            targetPos = minFinalBinPos;
          }

          out1 = calculateOutputToken1FromBinPosition(binState.token1BalanceScaled, currBinPos, targetPos);

          avgPos = uint104((uint256(currBinPos) + uint256(targetPos)) / 2);
          avgPrice = calculatePriceAtBinPosition(lowerPrice, upperPrice, avgPos, Math.Rounding.Floor);
          in0WithoutFee = calculateRequiredToken0(out1, avgPrice);
          totalIn0 = Math.ceilDiv(in0WithoutFee * (1e6 + currBinTotalSellFeeE6), 1e6);
        }
        if (totalIn0 < state.amountSpecifiedRemainingScaled && targetPos > minFinalBinPos) {
          totalIn0 = state.amountSpecifiedRemainingScaled;
        }

        if (totalIn0 > state.amountSpecifiedRemainingScaled) {
          uint256 delta = currBinPos - targetPos;
          // remaining < totalIn0 ⇒ ratio < 1 ⇒ scaledDelta ≤ delta ≤ currBinPos ≤ type(uint104).max
          uint104 scaledDelta =
            uint104(Math.mulDiv(delta, state.amountSpecifiedRemainingScaled, totalIn0, Math.Rounding.Ceil));
          if (scaledDelta == 0) scaledDelta = 1;
          targetPos = currBinPos > scaledDelta ? currBinPos - scaledDelta : 0;

          // Rescale out1 proportionally; remaining < totalIn0 ⇒ result ≤ out1 ≤ type(uint104).max
          out1 = (out1 * state.amountSpecifiedRemainingScaled) / totalIn0;
          totalIn0 = state.amountSpecifiedRemainingScaled;
        }
      }
      uint256 token0Fee = (totalIn0 * currBinTotalSellFeeE6) / (1e6 + currBinTotalSellFeeE6);

      uint256 protocolFeeAmount = (token0Fee * performanceFeeE6) / 1e6;

      binState.token1BalanceScaled -= out1.toUint104();
      binState.token0BalanceScaled = (uint256(binState.token0BalanceScaled) + totalIn0 - protocolFeeAmount).toUint104();

      state.amountSpecifiedRemainingScaled -= totalIn0;
      state.amountCalculatedScaled += out1;
      state.protocolFeeAmount += protocolFeeAmount;

      return (targetPos, out1);
    }
  }
}

