// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.33;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "@openzeppelin/contracts/utils/math/SafeCast.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuardTransient.sol";
import "./types/BinState.sol";
import "./libraries/SwapMath.sol";
import "./libraries/BinDataLibrary.sol";
import "./libraries/WrappedERC20.sol";
import "./interfaces/IPriceProvider.sol";
import "./interfaces/IMetricOmmPool/IMetricOmmPool.sol";
import "./interfaces/IMetricOmmPool/IMetricOmmPoolImmutables.sol";
import "./interfaces/callbacks/IMetricOmmSwapCallback.sol";

import "./Extsload.sol";

uint24 constant MAX_ADMIN_FEE_E6 = 200000;
uint24 constant MAX_PROTOCOL_FEE_E6 = 200000;

/**
 * @title MetricOmmPool
 * @notice Oracle-Based OMM Pool with separate bin accounting (Binary Search implementation)
 */
contract MetricOmmPool is IMetricOmmPool, Extsload, ReentrancyGuardTransient {
  using WrappedERC20 for address;
  using SwapMath for *;
  using BinDataLibrary for BinDataLibrary.BinData;
  using SafeCast for uint256;
  using SafeCast for int256;
  // ============ Immutables ============
  // All immutables are internal; read via getImmutables() external function

  address internal immutable FACTORY;
  address internal immutable TOKEN0;
  address internal immutable TOKEN1;

  /// @notice Multiplier to scale token0 external amounts to internal: 10^(max(18, decimals) - token0.decimals())
  uint256 internal immutable TOKEN_0_SCALE_MULTIPLIER;
  /// @notice Multiplier to scale token1 external amounts to internal: 10^(max(18, decimals) - token1.decimals())
  uint256 internal immutable TOKEN_1_SCALE_MULTIPLIER;

  uint104 internal immutable INITIAL_SCALED_TOKEN_0_PER_SHARE_E18;
  uint104 internal immutable INITIAL_SCALED_TOKEN_1_PER_SHARE_E18;
  uint104 internal immutable MINIMAL_MINTABLE_LIQUIDITY;

  uint256 internal immutable MAX_DRIFT_E8; // 1e8 = 100% ; 1 = 1e-4 bps
  uint256 internal immutable MAX_DRIFT_DECAY_PER_SECOND_E8; // 1e8 = 100%; 1 = 1e-4 bps
  bool internal immutable REPORT_SWAP_TO_PRICE_PROVIDER;

  int16 internal immutable LOWEST_BIN;
  int16 internal immutable HIGHEST_BIN;

  // ============ State Variables ============
  // +++++++++++ Used when swapping ++++++++++

  // Slot 0 (26 bytes used: 2+12+4+4+3 = 25, 7 bytes unused)
  int16 internal curBinIdx;
  uint104 internal curPosInBin;
  int32 internal curBinDistFromProvidedPriceE6;
  int32 internal driftE8; // 1e8 = 100%; 1 = 1e-4 bps
  uint24 internal performanceFeeE6; // 1e6 = 100%; 1 = 1e-2 bps; performanceFeeE6 = protocolFeeE6 + adminFeeE6

  // Slot 1 (32 bytes used: 16+16 = 32, packed exactly)
  uint128 internal totalScaledToken0InBins; // Sum of token0BalanceScaled across all bins
  uint128 internal totalScaledToken1InBins; // Sum of token1BalanceScaled across all bins

  mapping(int16 => BinState) internal _binsStates;
  mapping(int16 => uint104) internal _binsTotalShares;

  /// @dev Maps positionBinKey => shares for granular per-bin positions
  /// positionBinKey layout: [address(160 bits)] ++ [salt(72 bits)] ++ [bin(24 bits)]
  mapping(bytes32 => uint104) internal _positionBinShares;

  // ++++++++++ Unused when swapping ++++++++

  // Slot 5
  address internal admin;
  uint24 internal protocolFeeE6;
  uint24 internal adminFeeE6;
  uint48 internal lastTradeTimestamp;
  address internal adminFeeDestination;

  // ++++++++++ TESTING ONLY - make immutable in production ++++++++++
  address internal PRICE_PROVIDER; // /*immutable (mutable only for testing, in release will be immutable)*/;

  // ============ Modifiers ============

  modifier onlyFactory() {
    if (msg.sender != FACTORY) revert OnlyFactory();
    _;
  }

  modifier onlyAdmin() {
    if (msg.sender != admin) revert OnlyAdmin();
    _;
  }

  // ============ Immutables Reader ============

  /// @inheritdoc IMetricOmmPoolImmutables
  function getImmutables()
    external
    view
    returns (
      address factory,
      address priceProvider,
      address token0,
      address token1,
      uint104 initialToken0PerDistUnitPerShareE18,
      uint104 initialToken1PerDistUnitPerShareE18,
      uint104 minimalMintableLiquidity,
      bool reportSwapToPriceProvider,
      uint256 maxDriftE8,
      uint256 maxDriftDecayPerSecondE8,
      int16 lowestBin,
      int16 highestBin,
      uint256 token0ScaleMultiplier,
      uint256 token1ScaleMultiplier
    )
  {
    return (
      FACTORY,
      PRICE_PROVIDER,
      TOKEN0,
      TOKEN1,
      INITIAL_SCALED_TOKEN_0_PER_SHARE_E18,
      INITIAL_SCALED_TOKEN_1_PER_SHARE_E18,
      MINIMAL_MINTABLE_LIQUIDITY,
      REPORT_SWAP_TO_PRICE_PROVIDER,
      MAX_DRIFT_E8,
      MAX_DRIFT_DECAY_PER_SECOND_E8,
      LOWEST_BIN,
      HIGHEST_BIN,
      TOKEN_0_SCALE_MULTIPLIER,
      TOKEN_1_SCALE_MULTIPLIER
    );
  }

  // ============ Balance Helpers ============

  /// @notice Get the current balance of token0 held by the pool
  function balance0() internal view returns (uint256) {
    return TOKEN0.safeBalanceOf(address(this));
  }

  /// @notice Get the current balance of token1 held by the pool
  function balance1() internal view returns (uint256) {
    return TOKEN1.safeBalanceOf(address(this));
  }

  /// @notice Convert Scaled balance to external balance for token0
  function deltasScaledToExternal(int128 scaledDeltaAmount0, int128 scaledDeltaAmount1)
    internal
    view
    returns (int128 deltaAmount0, int128 deltaAmount1)
  {
    unchecked {
      if (scaledDeltaAmount0 < 0) {
        deltaAmount0 = scaledDeltaAmount0 / int128(uint128(TOKEN_0_SCALE_MULTIPLIER));
      } else {
        deltaAmount0 = int256(Math.ceilDiv(uint128(scaledDeltaAmount0), TOKEN_0_SCALE_MULTIPLIER)).toInt128();
      }
      if (scaledDeltaAmount1 < 0) {
        // Safe: TOKEN_X_SCALE_MULTIPLIER is max 10^18 which fits in int128
        deltaAmount1 = scaledDeltaAmount1 / int128(uint128(TOKEN_1_SCALE_MULTIPLIER));
      } else {
        deltaAmount1 = int256(Math.ceilDiv(uint128(scaledDeltaAmount1), TOKEN_1_SCALE_MULTIPLIER)).toInt128();
      }
    }
  }

  // ============ Constructor ============
  /// @dev the nonNegativeBinDataArray must have at least one bin (the 0 bin)
  constructor(
    address _factory,
    address _admin,
    address _token0,
    address _token1,
    address _priceProvider,
    uint104 initialScaledAmount0PerShareE18,
    uint104 initialScaledAmount1PerShareE18,
    uint104 minimalMintableLiquidity,
    bool reportSwapToPriceProvider,
    uint256 maxDriftE8,
    uint256 driftDecayPerSecondE8,
    uint24 _protocolFee,
    uint24 _adminFee,
    address _adminFeeDestination,
    int32 _curBinDistFromProvidedPrice,
    uint256[] memory nonNegativeBinDataArray,
    uint256[] memory negativeBinDataArray
  ) {
    if (nonNegativeBinDataArray.length == 0) revert BinArraysEmpty();

    FACTORY = _factory;
    admin = _admin;
    TOKEN0 = _token0;
    TOKEN1 = _token1;
    PRICE_PROVIDER = _priceProvider;

    // Calculate internal scaling decimals = max(18, token0.decimals(), token1.decimals())
    uint8 token0Decimals = IERC20Metadata(_token0).decimals();
    uint8 token1Decimals = IERC20Metadata(_token1).decimals();
    uint8 internalDecimals = 18;
    if (token0Decimals > internalDecimals) internalDecimals = token0Decimals;
    if (token1Decimals > internalDecimals) internalDecimals = token1Decimals;

    TOKEN_0_SCALE_MULTIPLIER = 10 ** (internalDecimals - token0Decimals);
    TOKEN_1_SCALE_MULTIPLIER = 10 ** (internalDecimals - token1Decimals);

    INITIAL_SCALED_TOKEN_0_PER_SHARE_E18 = initialScaledAmount0PerShareE18;
    INITIAL_SCALED_TOKEN_1_PER_SHARE_E18 = initialScaledAmount1PerShareE18;
    MINIMAL_MINTABLE_LIQUIDITY = minimalMintableLiquidity;
    REPORT_SWAP_TO_PRICE_PROVIDER = reportSwapToPriceProvider;

    MAX_DRIFT_E8 = maxDriftE8;
    MAX_DRIFT_DECAY_PER_SECOND_E8 = driftDecayPerSecondE8;

    performanceFeeE6 = _protocolFee + _adminFee;
    protocolFeeE6 = _protocolFee;
    adminFeeE6 = _adminFee;
    adminFeeDestination = _adminFeeDestination;

    curBinDistFromProvidedPriceE6 = _curBinDistFromProvidedPrice;

    // ============ Validate and Store Non-Negative Bins (0, 1, 2, ...) ============
    {
      if (nonNegativeBinDataArray.length > type(uint16).max / 10) {
        revert TooManyNonNegativeBins();
      }
      // Start validation from current bin state (we need to verify we won't overflow when traversing from current position)
      int64 cumulativeDistance = int64(_curBinDistFromProvidedPrice);
      int16 binIdx = 0;

      for (uint16 i = 0; i < nonNegativeBinDataArray.length; i++) {
        uint256 packed = nonNegativeBinDataArray[i];
        for (uint8 j = 0; j < 5; j++) {
          BinDataLibrary.BinData binData = BinDataLibrary.toBinData(packed, j);
          (uint16 length, uint16 buyFee, uint16 sellFee) = binData.unpack();

          if (length == 0) {
            if (j == 0) revert BinLengthZero(binIdx);
            break;
          }

          _binsStates[binIdx] = BinState({
            token0BalanceScaled: 0, token1BalanceScaled: 0, lengthE6: length, addFeeBuyE6: buyFee, addFeeSellE6: sellFee
          });

          cumulativeDistance += int64(uint64(length));
          if (cumulativeDistance > type(int32).max) {
            revert CumulativeDistanceArthmetic(binIdx, cumulativeDistance, true);
          }

          binIdx++;
        }
      }
      if (binIdx == 0) revert WrongBinArrays();
      HIGHEST_BIN = binIdx - 1;
    }

    // ============ Validate and Store Negative Bins (-1, -2, -3, ...) ============
    {
      if (negativeBinDataArray.length > type(uint16).max / 10) {
        revert TooManyNegativeBins();
      }
      // Start validation from current bin state (we need to verify we won't underflow when traversing from current position)
      int64 cumulativeDistance = int64(_curBinDistFromProvidedPrice);
      int16 binIdx = -1;

      for (uint16 i = 0; i < negativeBinDataArray.length; i++) {
        uint256 packed = negativeBinDataArray[i];
        for (uint8 j = 0; j < 5; j++) {
          BinDataLibrary.BinData binData = BinDataLibrary.toBinData(packed, j);
          (uint16 length, uint16 buyFee, uint16 sellFee) = binData.unpack();

          if (length == 0) {
            if (j == 0) revert BinLengthZero(binIdx);
            break;
          }

          _binsStates[binIdx] = BinState({
            token0BalanceScaled: 0, token1BalanceScaled: 0, lengthE6: length, addFeeBuyE6: buyFee, addFeeSellE6: sellFee
          });

          cumulativeDistance -= int64(uint64(length));
          if (cumulativeDistance < type(int32).min) {
            revert CumulativeDistanceArthmetic(binIdx, cumulativeDistance, false);
          }

          binIdx--;
        }
      }
      LOWEST_BIN = binIdx + 1;
    }

    emit Instantiated(
      _factory,
      _token0,
      _token1,
      _priceProvider,
      initialScaledAmount0PerShareE18,
      initialScaledAmount1PerShareE18,
      minimalMintableLiquidity,
      maxDriftE8,
      driftDecayPerSecondE8,
      _protocolFee,
      _adminFee,
      _adminFeeDestination
    );
  }

  // ============ Helper Functions ============

  /// @notice Pack owner, salt, and bin into a 32-byte key (no hashing needed)
  /// @dev Layout: [address(160)] | [salt(80)] | [bin(16)] = 256 bits
  function _positionBinKey(address owner, uint80 salt, int16 bin) internal pure returns (bytes32) {
    unchecked {
      return bytes32(
        (uint256(uint160(owner)) << 96) // address in upper 160 bits
          | (uint256(salt) << 16) // salt in middle 80 bits
          | uint256(uint16(bin)) // bin in lower 16 bits
      );
    }
  }

  /// @dev Converts distance-from-mid-price (E6 units) to an absolute price Q64.64.
  /// Result ≤ type(uint128).max when midPriceX64 ≤ type(uint128).max and |distanceValueE6| < 1e6.
  function distanceE6ToPriceX64(int32 distanceValueE6, uint256 midPriceX64, Math.Rounding rounding)
    internal
    pure
    returns (uint256)
  {
    unchecked {
      if (distanceValueE6 >= 0) {
        return Math.mulDiv(midPriceX64, 1e6 + uint256(int256(distanceValueE6)), 1e6, rounding);
      } else {
        return Math.mulDiv(midPriceX64, 1e6 - uint256(int256(-distanceValueE6)), 1e6, rounding);
      }
    }
  }

  // ============ Liquidity Management ============

  /// @inheritdoc IMetricOmmPoolActions
  function modifyLiquidity(uint80 salt, LiquidityDelta[] calldata deltas, int128 specAmount0, int128 specAmount1)
    external
    nonReentrant
    returns (int128 amount0Delta, int128 amount1Delta)
  {
    unchecked {
      if (deltas.length == 0) return (0, 0);

      // Track deltas in INTERNAL (scaled) units
      int128 totalToken0DeltaScaled = 0;
      int128 totalToken1DeltaScaled = 0;

      for (uint256 i = 0; i < deltas.length; i++) {
        int16 bin = deltas[i].bin;
        int104 deltaShares = deltas[i].deltaShares;

        if (bin < LOWEST_BIN || bin > HIGHEST_BIN) revert InvalidBinIndex(bin);
        if (deltaShares == 0) continue;

        bytes32 posKey = _positionBinKey(msg.sender, salt, bin);
        BinState memory binState = _binsStates[bin];
        uint104 binTotalSharesVal = _binsTotalShares[bin];
        uint104 userShares = _positionBinShares[posKey];

        if (deltaShares > 0) {
          uint104 sharesToAdd = uint104(deltaShares);

          uint104 amount0Scaled = 0;
          uint104 amount1Scaled = 0;
          if (binTotalSharesVal == 0) {
            if (bin < curBinIdx) {
              amount1Scaled =
                (Math.ceilDiv(uint256(INITIAL_SCALED_TOKEN_1_PER_SHARE_E18) * sharesToAdd, 1e18)).toUint104();
            } else if (bin > curBinIdx) {
              amount0Scaled =
                (Math.ceilDiv(uint256(INITIAL_SCALED_TOKEN_0_PER_SHARE_E18) * sharesToAdd, 1e18)).toUint104();
            } else {
              uint256 token0Proportion = type(uint104).max - curPosInBin;
              uint256 token1Proportion = curPosInBin;
              amount0Scaled = (Math.mulDiv(
                  token0Proportion * INITIAL_SCALED_TOKEN_0_PER_SHARE_E18,
                  sharesToAdd,
                  uint256(type(uint104).max) * 1e18,
                  Math.Rounding.Ceil
                ))
              .toUint104();
              amount1Scaled = (Math.mulDiv(
                  token1Proportion * INITIAL_SCALED_TOKEN_1_PER_SHARE_E18,
                  sharesToAdd,
                  uint256(type(uint104).max) * 1e18,
                  Math.Rounding.Ceil
                ))
              .toUint104();
            }
          } else {
            amount0Scaled =
              (Math.ceilDiv(uint256(binState.token0BalanceScaled) * sharesToAdd, binTotalSharesVal)).toUint104();
            amount1Scaled =
              (Math.ceilDiv(uint256(binState.token1BalanceScaled) * sharesToAdd, binTotalSharesVal)).toUint104();
          }
          if (amount0Scaled > 0) {
            totalToken0DeltaScaled += int128(uint128(amount0Scaled));
            binState.token0BalanceScaled = (uint256(binState.token0BalanceScaled) + amount0Scaled).toUint104();
          }
          if (amount1Scaled > 0) {
            totalToken1DeltaScaled += int128(uint128(amount1Scaled));
            binState.token1BalanceScaled = (uint256(binState.token1BalanceScaled) + amount1Scaled).toUint104();
          }
          _binsTotalShares[bin] = (uint256(binTotalSharesVal) + sharesToAdd).toUint104();
          _positionBinShares[posKey] = (uint256(userShares) + sharesToAdd).toUint104();
        } else {
          uint104 sharesToRemove = uint104(-deltaShares);

          if (userShares < sharesToRemove) revert InsufficientLiquidity(sharesToRemove, userShares);

          uint128 amount0Scaled = uint128((uint256(binState.token0BalanceScaled) * sharesToRemove) / binTotalSharesVal);
          uint128 amount1Scaled = uint128((uint256(binState.token1BalanceScaled) * sharesToRemove) / binTotalSharesVal);

          binState.token0BalanceScaled -= uint104(amount0Scaled);
          binState.token1BalanceScaled -= uint104(amount1Scaled);
          _binsTotalShares[bin] = binTotalSharesVal - sharesToRemove;
          _positionBinShares[posKey] = userShares - sharesToRemove;

          totalToken0DeltaScaled -= int128(uint128(amount0Scaled));
          totalToken1DeltaScaled -= int128(uint128(amount1Scaled));
        }

        _binsStates[bin] = binState;
      }

      // Update bin totals: positive delta = tokens added to bins, negative = removed
      if (totalToken0DeltaScaled > 0) {
        totalScaledToken0InBins = (uint256(totalScaledToken0InBins) + uint128(totalToken0DeltaScaled)).toUint128();
      } else if (totalToken0DeltaScaled < 0) {
        totalScaledToken0InBins = (uint256(totalScaledToken0InBins) - uint128(-totalToken0DeltaScaled)).toUint128();
      }
      if (totalToken1DeltaScaled > 0) {
        totalScaledToken1InBins = (uint256(totalScaledToken1InBins) + uint128(totalToken1DeltaScaled)).toUint128();
      } else if (totalToken1DeltaScaled < 0) {
        totalScaledToken1InBins = (uint256(totalScaledToken1InBins) - uint128(-totalToken1DeltaScaled)).toUint128();
      }

      (int128 totalToken0Delta, int128 totalToken1Delta) =
        deltasScaledToExternal(totalToken0DeltaScaled, totalToken1DeltaScaled);

      if (totalToken0Delta > specAmount0) {
        revert Amount0BelowSpecified(totalToken0Delta, specAmount0);
      }
      if (totalToken1Delta > specAmount1) {
        revert Amount1BelowSpecified(totalToken1Delta, specAmount1);
      }

      if (totalToken0Delta > 0) {
        TOKEN0.safeTransferFrom(msg.sender, address(this), uint128(totalToken0Delta));
      } else if (totalToken0Delta < 0) {
        TOKEN0.safeTransfer(msg.sender, uint128(-totalToken0Delta));
      }

      if (totalToken1Delta > 0) {
        TOKEN1.safeTransferFrom(msg.sender, address(this), uint128(totalToken1Delta));
      } else if (totalToken1Delta < 0) {
        TOKEN1.safeTransfer(msg.sender, uint128(-totalToken1Delta));
      }

      emit LiquidityModified(
        msg.sender, salt, totalToken0Delta, totalToken1Delta, _extractBins(deltas), _extractDeltaShares(deltas)
      );

      return (totalToken0Delta, totalToken1Delta);
    }
  }

  function _extractBins(LiquidityDelta[] calldata deltas) internal pure returns (int16[] memory bins) {
    bins = new int16[](deltas.length);
    for (uint256 i = 0; i < deltas.length; i++) {
      bins[i] = deltas[i].bin;
    }
  }

  function _extractDeltaShares(LiquidityDelta[] calldata deltas) internal pure returns (int104[] memory deltaShares) {
    deltaShares = new int104[](deltas.length);
    for (uint256 i = 0; i < deltas.length; i++) {
      deltaShares[i] = deltas[i].deltaShares;
    }
  }

  // ============ Swap Functions ============

  function _executeSwap(bool zeroForOne, int128 amountSpecified, SwapMath.InternalSwapParams memory params)
    internal
    returns (int128 amount0Delta, int128 amount1Delta)
  {
    unchecked {
      int128 amount0DeltaScaled;
      int128 amount1DeltaScaled;
      uint256 protocolFeeAmountScaled;

      // Safe: TOKEN_X_SCALE_MULTIPLIER ≤ 10^18, |amountSpecified| ≤ int128.max ⇒ product < 2^196 < uint256.max
      if (amountSpecified > 0) {
        if (zeroForOne) {
          uint256 amountInScaled = TOKEN_0_SCALE_MULTIPLIER * uint128(amountSpecified);
          uint256 amountOutScaled;
          (amountInScaled, amountOutScaled, protocolFeeAmountScaled) =
            _swapToken0ForToken1SpecifiedInput(amountInScaled, params);
          amount0DeltaScaled = int256(amountInScaled).toInt128();
          amount1DeltaScaled = -int256(amountOutScaled).toInt128();
        } else {
          uint256 amountInScaled = TOKEN_1_SCALE_MULTIPLIER * uint128(amountSpecified);
          uint256 amountOutScaled;
          (amountInScaled, amountOutScaled, protocolFeeAmountScaled) =
            _swapToken1ForToken0SpecifiedInput(amountInScaled, params);
          amount0DeltaScaled = -int256(amountOutScaled).toInt128();
          amount1DeltaScaled = int256(amountInScaled).toInt128();
        }
      } else {
        if (zeroForOne) {
          uint256 amountOutScaled = TOKEN_1_SCALE_MULTIPLIER * uint128(uint256(-int256(amountSpecified)));
          uint256 amountInScaled;
          (amountInScaled, amountOutScaled, protocolFeeAmountScaled) =
            _swapToken0ForToken1SpecifiedOutput(amountOutScaled, params);
          amount0DeltaScaled = int256(amountInScaled).toInt128();
          amount1DeltaScaled = -int256(amountOutScaled).toInt128();
        } else {
          uint256 amountOutScaled = TOKEN_0_SCALE_MULTIPLIER * uint128(uint256(-int256(amountSpecified)));
          uint256 amountInScaled;
          (amountInScaled, amountOutScaled, protocolFeeAmountScaled) =
            _swapToken1ForToken0SpecifiedOutput(amountOutScaled, params);
          amount0DeltaScaled = -int256(amountOutScaled).toInt128();
          amount1DeltaScaled = int256(amountInScaled).toInt128();
        }
      }

      // Update bin totals: fee is charged on the input token and does NOT enter bins.
      // For zeroForOne: token0 enters bins (minus fee), token1 leaves bins.
      // For !zeroForOne: token1 enters bins (minus fee), token0 leaves bins.
      if (zeroForOne) {
        totalScaledToken0InBins =
          (uint256(totalScaledToken0InBins) + uint128(amount0DeltaScaled) - protocolFeeAmountScaled).toUint128();
        totalScaledToken1InBins = (uint256(totalScaledToken1InBins) - uint128(-amount1DeltaScaled)).toUint128();
      } else {
        totalScaledToken1InBins =
          (uint256(totalScaledToken1InBins) + uint128(amount1DeltaScaled) - protocolFeeAmountScaled).toUint128();
        totalScaledToken0InBins = (uint256(totalScaledToken0InBins) - uint128(-amount0DeltaScaled)).toUint128();
      }

      (amount0Delta, amount1Delta) = deltasScaledToExternal(amount0DeltaScaled, amount1DeltaScaled);
    }
  }

  function swap(address recipient, bool zeroForOne, int128 amountSpecified, uint128 priceLimitX64, bytes calldata data)
    external
    nonReentrant
    returns (int128 amount0Delta, int128 amount1Delta)
  {
    require(amountSpecified != 0, InvalidAmount());

    (uint128 midPriceX64, uint256 baseFeeE6) = _getMidPriceAndBaseFeeE6();
    SwapMath.InternalSwapParams memory params =
      SwapMath.InternalSwapParams({midPriceX64: midPriceX64, baseFeeE6: baseFeeE6, priceLimitX64: priceLimitX64});

    (amount0Delta, amount1Delta) = _executeSwap(zeroForOne, amountSpecified, params);

    if (zeroForOne) {
      if (amount1Delta < 0) {
        TOKEN1.safeTransfer(recipient, uint256(-int256(amount1Delta)));
      }

      uint256 balance0Before = balance0();
      IMetricOmmSwapCallback(msg.sender).metricOmmSwapCallback(TOKEN0, TOKEN1, amount0Delta, amount1Delta, data);
      if (amount0Delta > 0 && balance0Before + uint128(amount0Delta) > balance0()) {
        revert IncorrectDelta();
      }
    } else {
      if (amount0Delta < 0) {
        TOKEN0.safeTransfer(recipient, uint256(-int256(amount0Delta)));
      }

      uint256 balance1Before = balance1();
      IMetricOmmSwapCallback(msg.sender).metricOmmSwapCallback(TOKEN0, TOKEN1, amount0Delta, amount1Delta, data);
      // SafeCast for amount1Delta to uint256
      if (amount1Delta > 0 && balance1Before + uint128(amount1Delta) > balance1()) {
        revert IncorrectDelta();
      }
    }

    if (REPORT_SWAP_TO_PRICE_PROVIDER) {
      try IPriceProviderSwapReporter(PRICE_PROVIDER)
        .reportSwap(
          msg.sender,
          recipient,
          zeroForOne,
          amountSpecified,
          priceLimitX64,
          amount0Delta,
          amount1Delta,
          curBinIdx,
          curPosInBin
        ) {}
        catch (bytes memory) {}
    }

    emit Swap(msg.sender, recipient, amountSpecified > 0, amount0Delta, amount1Delta, curBinIdx, curPosInBin);
  }

  /// @dev Helper function to persist bin state to storage. Reduces stack depth in swap functions.
  function _saveBinState(int16 binIdx, BinState memory binState) internal {
    _binsStates[binIdx] = binState;
  }

  function _getMidPriceAndBaseFeeE6() internal view returns (uint128 midPriceX64, uint256 feeE6) {
    try IPriceProvider(PRICE_PROVIDER).getBidAndAskPrice() returns (uint128 bidPriceX64, uint128 askPriceX64) {
      if (bidPriceX64 > askPriceX64) revert BidGreaterThanAsk();
      if (bidPriceX64 == 0) revert BidIsZero();

      midPriceX64 = Math.sqrt(uint256(bidPriceX64) * uint256(askPriceX64)).toUint128();

      feeE6 = Math.sqrt(Math.mulDiv(uint256(askPriceX64), 1e12, uint256(bidPriceX64), Math.Rounding.Ceil)) - (1e6 - 1);
    } catch (bytes memory reason) {
      revert WrappedError(PRICE_PROVIDER, IPriceProvider.getBidAndAskPrice.selector, reason, "");
    }
  }

  function _decayDrift() internal {
    unchecked {
      uint256 timestamp = block.timestamp;
      uint256 timeDelta = timestamp - lastTradeTimestamp;
      if (timeDelta > 0) {
        int256 decayE8 = int256(MAX_DRIFT_DECAY_PER_SECOND_E8 * timeDelta);
        int256 driftE8Cached = driftE8;
        if (driftE8Cached >= 0) {
          if (decayE8 >= driftE8Cached) driftE8Cached = 0;
          else driftE8Cached -= decayE8;
        } else {
          if (decayE8 >= -driftE8Cached) driftE8Cached = 0;
          else driftE8Cached += decayE8;
        }
        driftE8 = driftE8Cached.toInt32();
        // Assumption: block.timestamp <= type(uint48).max for the lifetime of this system.
        lastTradeTimestamp = timestamp.toUint48();
      }
    }
  }

  /// @dev Applies drift decay and computes an effective price limit constrained by available drift.
  /// @param midPriceX64 Assumes midPriceX64 <= type(uint128).max.
  /// @param priceLimitX64 Assumes priceLimitX64 <= type(uint128).max.
  /// @return adjustedPriceLimitX64 Resulting adjusted limit; assumes adjustedPriceLimitX64 <= type(uint128).max.
  function _decayDriftAndCalculateLimit(uint256 midPriceX64, uint256 priceLimitX64, bool goingUp)
    internal
    returns (uint256 adjustedPriceLimitX64)
  {
    _decayDrift();
    unchecked {
      if (goingUp) {
        if (int256(driftE8) >= int256(MAX_DRIFT_E8)) {
          return midPriceX64;
        }
        uint256 availableDriftE8 = uint256(int256(MAX_DRIFT_E8) - int256(driftE8));
        uint256 driftLimitX64 = Math.ceilDiv(midPriceX64 * (1e8 + availableDriftE8), 1e8);
        adjustedPriceLimitX64 = priceLimitX64 > driftLimitX64 ? driftLimitX64 : priceLimitX64;
      } else {
        if (int256(-driftE8) >= int256(MAX_DRIFT_E8)) {
          return midPriceX64;
        }
        uint256 availableDriftE8 = uint256(int256(MAX_DRIFT_E8) + int256(driftE8));
        uint256 driftLimitX64 = (midPriceX64 * (1e8 - availableDriftE8)) / 1e8;
        adjustedPriceLimitX64 = priceLimitX64 < driftLimitX64 ? driftLimitX64 : priceLimitX64;
      }

      return adjustedPriceLimitX64;
    }
  }

  /// @dev Loads current swap state and computes bin price bounds for current bin.
  /// @param amountSpecifiedScaled Assumes amountSpecifiedScaled <= type(uint128).max.
  function _updateDriftAndGetInitialStateForSwap(
    bool zeroForOne,
    bool specifiedOut,
    SwapMath.InternalSwapParams memory params,
    uint256 amountSpecifiedScaled
  )
    internal
    returns (
      BinState memory binState,
      SwapMath.SwapState memory state,
      int16 curBinIdxCache,
      uint104 curPosInBinCache,
      int32 curBinDistE6Cache,
      uint256 lowerPriceX64,
      uint256 upperPriceX64,
      uint256 initialPriceX64
    )
  {
    params.priceLimitX64 = _decayDriftAndCalculateLimit(params.midPriceX64, params.priceLimitX64, !zeroForOne);

    state = SwapMath.SwapState({
      amountSpecifiedRemainingScaled: amountSpecifiedScaled, amountCalculatedScaled: 0, protocolFeeAmount: 0
    });

    curBinIdxCache = curBinIdx;
    curPosInBinCache = curPosInBin;
    curBinDistE6Cache = curBinDistFromProvidedPriceE6;

    binState = _binsStates[curBinIdxCache];

    Math.Rounding rounding = zeroForOne ? Math.Rounding.Floor : Math.Rounding.Ceil;

    lowerPriceX64 = distanceE6ToPriceX64(curBinDistE6Cache, params.midPriceX64, rounding);
    upperPriceX64 = distanceE6ToPriceX64(
      // Safe: lengthE6 is uint16 which fits in int32
      curBinDistE6Cache + int32(uint32(binState.lengthE6)),
      params.midPriceX64,
      rounding
    );

    Math.Rounding posRounding = (zeroForOne == specifiedOut) ? Math.Rounding.Ceil : Math.Rounding.Floor;

    initialPriceX64 = SwapMath.calculatePriceAtBinPosition(lowerPriceX64, upperPriceX64, curPosInBinCache, posRounding);
  }

  function _finalizeSwap(
    int16 curBinIdxCache,
    uint104 curPosInBinCache,
    int32 curBinDistE6Cache,
    uint256 initialPriceX64,
    uint256 lowerPriceX64,
    uint256 upperPriceX64,
    bool zeroForOne
  ) internal {
    curBinIdx = curBinIdxCache;
    curPosInBin = curPosInBinCache;
    curBinDistFromProvidedPriceE6 = curBinDistE6Cache;

    Math.Rounding rounding = zeroForOne ? Math.Rounding.Floor : Math.Rounding.Ceil;
    uint256 finalPriceX64 =
      SwapMath.calculatePriceAtBinPosition(lowerPriceX64, upperPriceX64, curPosInBinCache, rounding);

    uint256 priceChangeX64 = zeroForOne ? initialPriceX64 - finalPriceX64 : finalPriceX64 - initialPriceX64;
    int256 tradeDriftE8 = ((priceChangeX64 * 1e8) / initialPriceX64).toInt256();

    if (zeroForOne) {
      driftE8 = (int256(driftE8) - tradeDriftE8).toInt32();
    } else {
      driftE8 = (int256(driftE8) + tradeDriftE8).toInt32();
    }
  }

  ///@dev Input token1, specified output token0
  ///@return (amountInScaled, amountOutScaled, protocolFeeAmountScaled)
  function _swapToken1ForToken0SpecifiedOutput(uint256 amountOutScaled, SwapMath.InternalSwapParams memory params)
    internal
    returns (uint256, uint256, uint256)
  {
    {
      uint256 totalAvailableToken0Scaled = totalScaledToken0InBins;
      if (amountOutScaled > totalAvailableToken0Scaled) {
        amountOutScaled = totalAvailableToken0Scaled;
      }
    }
    (
      BinState memory binState,
      SwapMath.SwapState memory state,
      int16 curBinIdxCache,
      uint104 curPosInBinCache,
      int32 curBinDistE6Cache,
      uint256 lowerPriceX64,
      uint256 upperPriceX64,
      uint256 initialPriceX64
    ) = _updateDriftAndGetInitialStateForSwap(false, true, params, amountOutScaled);

    if (params.priceLimitX64 <= initialPriceX64) {
      return (0, 0, 0);
    }

    while (state.amountSpecifiedRemainingScaled > 0) {
      bool nonEmptyBin = true;
      if (binState.token0BalanceScaled == 0 || curPosInBinCache >= type(uint104).max) {
        if (params.priceLimitX64 <= upperPriceX64) {
          break;
        }
        nonEmptyBin = false;
      }

      if (nonEmptyBin) {
        (curPosInBinCache) = SwapMath.buyToken0InBinSpecifiedOut(
          binState,
          curPosInBinCache,
          state,
          params.baseFeeE6 + binState.addFeeBuyE6,
          lowerPriceX64,
          upperPriceX64,
          params.priceLimitX64,
          performanceFeeE6
        );

        _saveBinState(curBinIdxCache, binState);
      }

      if (curPosInBinCache >= type(uint104).max || !nonEmptyBin) {
        if (curBinIdxCache >= HIGHEST_BIN) {
          break;
        }
        curBinIdxCache++;
        curPosInBinCache = 0;
        curBinDistE6Cache += int32(uint32(binState.lengthE6));

        lowerPriceX64 = upperPriceX64;
        binState = _binsStates[curBinIdxCache];
        upperPriceX64 = distanceE6ToPriceX64(
          curBinDistE6Cache + int32(uint32(binState.lengthE6)), params.midPriceX64, Math.Rounding.Ceil
        );
      } else {
        break;
      }
    }

    _finalizeSwap(
      curBinIdxCache, curPosInBinCache, curBinDistE6Cache, initialPriceX64, lowerPriceX64, upperPriceX64, false
    );

    return
      (state.amountCalculatedScaled, amountOutScaled - state.amountSpecifiedRemainingScaled, state.protocolFeeAmount);
  }

  ///@dev Specified input token1, output token0
  ///@return (amountInScaled, amountOutScaled, protocolFeeAmountScaled)
  function _swapToken1ForToken0SpecifiedInput(uint256 amountInScaled, SwapMath.InternalSwapParams memory params)
    internal
    returns (uint256, uint256, uint256)
  {
    (
      BinState memory binState,
      SwapMath.SwapState memory state,
      int16 curBinIdxCache,
      uint104 curPosInBinCache,
      int32 curBinDistE6Cache,
      uint256 lowerPriceX64,
      uint256 upperPriceX64,
      uint256 initialPriceX64
    ) = _updateDriftAndGetInitialStateForSwap(false, false, params, amountInScaled);

    if (params.priceLimitX64 <= initialPriceX64) {
      return (0, 0, 0);
    }

    uint256 totalAvailableToken0Scaled = totalScaledToken0InBins;

    while (state.amountSpecifiedRemainingScaled > 0) {
      bool nonEmptyBin = true;
      if (binState.token0BalanceScaled == 0 || curPosInBinCache >= type(uint104).max) {
        if (params.priceLimitX64 != 0 && params.priceLimitX64 <= upperPriceX64) {
          break;
        }
        if (totalAvailableToken0Scaled == 0) {
          break;
        }
        nonEmptyBin = false;
      }

      if (nonEmptyBin) {
        uint256 outToken0Amount;
        (curPosInBinCache, outToken0Amount) = SwapMath.buyToken0InBinSpecifiedIn(
          binState,
          curPosInBinCache,
          state,
          params.baseFeeE6 + binState.addFeeBuyE6,
          lowerPriceX64,
          upperPriceX64,
          params.priceLimitX64,
          performanceFeeE6
        );

        _saveBinState(curBinIdxCache, binState);
        totalAvailableToken0Scaled -= outToken0Amount;
      }

      if (curPosInBinCache >= type(uint104).max || !nonEmptyBin) {
        if (curBinIdxCache >= HIGHEST_BIN) {
          break;
        }
        curBinIdxCache++;
        curPosInBinCache = 0;
        curBinDistE6Cache += int32(uint32(binState.lengthE6));

        lowerPriceX64 = upperPriceX64;
        binState = _binsStates[curBinIdxCache];
        upperPriceX64 = distanceE6ToPriceX64(
          curBinDistE6Cache + int32(uint32(binState.lengthE6)), params.midPriceX64, Math.Rounding.Ceil
        );
      } else {
        break;
      }
    }

    _finalizeSwap(
      curBinIdxCache, curPosInBinCache, curBinDistE6Cache, initialPriceX64, lowerPriceX64, upperPriceX64, false
    );

    return
      (amountInScaled - state.amountSpecifiedRemainingScaled, state.amountCalculatedScaled, state.protocolFeeAmount);
  }

  ///@dev Input token0, specified output token1
  ///@return (amountInScaled, amountOutScaled, protocolFeeAmountScaled)
  function _swapToken0ForToken1SpecifiedOutput(uint256 amountOutScaled, SwapMath.InternalSwapParams memory params)
    internal
    returns (uint256, uint256, uint256)
  {
    {
      uint256 totalAvailableToken1Scaled = totalScaledToken1InBins;
      if (amountOutScaled > totalAvailableToken1Scaled) {
        amountOutScaled = totalAvailableToken1Scaled;
      }
    }

    (
      BinState memory binState,
      SwapMath.SwapState memory state,
      int16 curBinIdxCache,
      uint104 curPosInBinCache,
      int32 curBinDistE6Cache,
      uint256 lowerPriceX64,
      uint256 upperPriceX64,
      uint256 initialPriceX64
    ) = _updateDriftAndGetInitialStateForSwap(true, true, params, amountOutScaled);

    if (params.priceLimitX64 >= initialPriceX64) {
      return (0, 0, 0);
    }

    while (state.amountSpecifiedRemainingScaled > 0) {
      bool nonEmptyBin = true;
      if (binState.token1BalanceScaled == 0 || curPosInBinCache == 0) {
        if (params.priceLimitX64 >= lowerPriceX64) {
          break;
        }
        nonEmptyBin = false;
      }

      if (nonEmptyBin) {
        (curPosInBinCache) = SwapMath.buyToken1InBinSpecifiedOut(
          binState,
          curPosInBinCache,
          state,
          params.baseFeeE6 + binState.addFeeSellE6,
          lowerPriceX64,
          upperPriceX64,
          params.priceLimitX64,
          performanceFeeE6
        );

        _saveBinState(curBinIdxCache, binState);
      }

      if (curPosInBinCache == 0 || !nonEmptyBin) {
        if (curBinIdxCache <= LOWEST_BIN) {
          break;
        }
        curBinIdxCache--;
        binState = _binsStates[curBinIdxCache];
        curPosInBinCache = type(uint104).max;
        curBinDistE6Cache -= int32(uint32(binState.lengthE6));

        upperPriceX64 = lowerPriceX64;
        lowerPriceX64 = distanceE6ToPriceX64(curBinDistE6Cache, params.midPriceX64, Math.Rounding.Floor);
      } else {
        break;
      }
    }

    _finalizeSwap(
      curBinIdxCache, curPosInBinCache, curBinDistE6Cache, initialPriceX64, lowerPriceX64, upperPriceX64, true
    );

    return
      (state.amountCalculatedScaled, amountOutScaled - state.amountSpecifiedRemainingScaled, state.protocolFeeAmount);
  }

  ///@dev Specified input token0, output token1
  ///@return (amountInScaled, amountOutScaled, protocolFeeAmountScaled)
  function _swapToken0ForToken1SpecifiedInput(uint256 amountInScaled, SwapMath.InternalSwapParams memory params)
    internal
    returns (uint256, uint256, uint256)
  {
    (
      BinState memory binState,
      SwapMath.SwapState memory state,
      int16 curBinIdxCache,
      uint104 curPosInBinCache,
      int32 curBinDistE6Cache,
      uint256 lowerPriceX64,
      uint256 upperPriceX64,
      uint256 initialPriceX64
    ) = _updateDriftAndGetInitialStateForSwap(true, false, params, amountInScaled);

    if (params.priceLimitX64 >= initialPriceX64) {
      return (0, 0, 0);
    }

    uint256 totalAvailableToken1Scaled = totalScaledToken1InBins;

    while (state.amountSpecifiedRemainingScaled > 0) {
      bool nonEmptyBin = true;
      if (binState.token1BalanceScaled == 0 || curPosInBinCache == 0) {
        if (params.priceLimitX64 != 0 && params.priceLimitX64 >= lowerPriceX64) {
          break;
        }
        if (totalAvailableToken1Scaled == 0) {
          break;
        }
        nonEmptyBin = false;
      }

      if (nonEmptyBin) {
        uint256 outToken1Amount;

        (curPosInBinCache, outToken1Amount) = SwapMath.buyToken1InBinSpecifiedIn(
          binState,
          curPosInBinCache,
          state,
          params.baseFeeE6 + binState.addFeeSellE6,
          lowerPriceX64,
          upperPriceX64,
          params.priceLimitX64,
          performanceFeeE6
        );

        _saveBinState(curBinIdxCache, binState);
        totalAvailableToken1Scaled -= outToken1Amount;
      }

      if (curPosInBinCache == 0 || !nonEmptyBin) {
        if (curBinIdxCache <= LOWEST_BIN) {
          break;
        }
        curBinIdxCache--;
        binState = _binsStates[curBinIdxCache];
        curPosInBinCache = type(uint104).max;
        curBinDistE6Cache -= int32(uint32(binState.lengthE6));

        upperPriceX64 = lowerPriceX64;
        lowerPriceX64 = distanceE6ToPriceX64(curBinDistE6Cache, params.midPriceX64, Math.Rounding.Floor);
      } else {
        break;
      }
    }

    _finalizeSwap(
      curBinIdxCache, curPosInBinCache, curBinDistE6Cache, initialPriceX64, lowerPriceX64, upperPriceX64, true
    );

    return
      (amountInScaled - state.amountSpecifiedRemainingScaled, state.amountCalculatedScaled, state.protocolFeeAmount);
  }

  function _collectProtocolFees() internal {
    if (performanceFeeE6 == 0) {
      return;
    }
    unchecked {
      // Collectable = actual balance minus what belongs in bins.
      // This naturally includes accumulated protocol/admin fees AND any accidentally donated tokens.
      uint256 surplus0Scaled = (balance0() * TOKEN_0_SCALE_MULTIPLIER) - uint256(totalScaledToken0InBins);
      uint256 surplus1Scaled = (balance1() * TOKEN_1_SCALE_MULTIPLIER) - uint256(totalScaledToken1InBins);

      uint256 amount0 = surplus0Scaled / TOKEN_0_SCALE_MULTIPLIER;
      uint256 amount1 = surplus1Scaled / TOKEN_1_SCALE_MULTIPLIER;

      // Safe: adminFeeE6 ≤ performanceFeeE6, so toAdmin ≤ amount
      uint256 amount0ToAdmin = (amount0 * adminFeeE6) / performanceFeeE6;
      uint256 amount1ToAdmin = (amount1 * adminFeeE6) / performanceFeeE6;

      uint256 amount0ToProtocol = amount0 - amount0ToAdmin;
      uint256 amount1ToProtocol = amount1 - amount1ToAdmin;

      if (amount0ToAdmin > 0) {
        TOKEN0.safeTransfer(adminFeeDestination, amount0ToAdmin);
      }
      if (amount1ToAdmin > 0) {
        TOKEN1.safeTransfer(adminFeeDestination, amount1ToAdmin);
      }

      if (amount0ToProtocol > 0) {
        TOKEN0.safeTransfer(FACTORY, amount0ToProtocol);
      }
      if (amount1ToProtocol > 0) {
        TOKEN1.safeTransfer(FACTORY, amount1ToProtocol);
      }

      emit ProtocolFeesCollected(amount0ToProtocol, amount1ToProtocol, amount0ToAdmin, amount1ToAdmin);
    }
  }

  function collectProtocolFees() external nonReentrant {
    _collectProtocolFees();
  }

  function setProtocolFee(uint24 newProtocolFeeE6) external onlyFactory nonReentrant {
    _collectProtocolFees();

    if (newProtocolFeeE6 > MAX_PROTOCOL_FEE_E6) revert ToHighNewFee();

    unchecked {
      performanceFeeE6 = newProtocolFeeE6 + adminFeeE6;
    }
    protocolFeeE6 = newProtocolFeeE6;
    emit ProtocolFeeUpdated(newProtocolFeeE6);
  }

  function setAdminFee(uint24 newAdminFeeE6) external onlyAdmin nonReentrant {
    _collectProtocolFees();

    if (newAdminFeeE6 > MAX_ADMIN_FEE_E6) revert ToHighNewFee();

    unchecked {
      performanceFeeE6 = protocolFeeE6 + newAdminFeeE6;
    }
    adminFeeE6 = newAdminFeeE6;
    emit AdminFeeUpdated(newAdminFeeE6);
  }

  function setAdminFeeDestination(address newAdminFeeDestination) external onlyAdmin {
    adminFeeDestination = newAdminFeeDestination;

    emit AdminFeeDestinationUpdated(newAdminFeeDestination);
  }

  // Just for testing
  function setPriceProvider(address newPriceProvider) external onlyAdmin {
    PRICE_PROVIDER = newPriceProvider;

    emit PriceProviderUpdated(newPriceProvider);
  }

  // ============ simulate swap ==============

  function simulateSwapAndRevert(
    bool zeroForOne,
    int128 amountSpecified,
    uint128 priceLimitX64,
    uint128 bidPriceX64,
    uint128 askPriceX64
  ) external override returns (int128 amount0Delta, int128 amount1Delta) {
    if (amountSpecified == 0) return (0, 0);
    if (bidPriceX64 > askPriceX64) revert BidGreaterThanAsk();
    if (bidPriceX64 == 0) revert BidIsZero();

    uint128 midPriceX64 = Math.sqrt(uint256(bidPriceX64) * uint256(askPriceX64)).toUint128();
    uint256 baseFeeE6 =
      Math.sqrt(Math.mulDiv(uint256(askPriceX64), 1e12, uint256(bidPriceX64), Math.Rounding.Ceil)) - (1e6 - 1);

    SwapMath.InternalSwapParams memory params =
      SwapMath.InternalSwapParams({midPriceX64: midPriceX64, baseFeeE6: baseFeeE6, priceLimitX64: priceLimitX64});

