pragma solidity ^0.8.33;

import "./MetricOmmPool.sol";

/// @title MetricOmmPoolDeployer
/// @notice Deploys MetricOmmPool instances with embedded bytecode, only callable by the factory
contract MetricOmmPoolDeployer {
  /// @notice The factory address that is allowed to deploy pools
  address public immutable factory;

  /// @notice Thrown when caller is not the factory
  error OnlyFactory();

  /// @notice Parameters for deploying a pool
  struct DeployParams {
    bytes32 salt;
    address factory;
    address admin;
    address token0;
    address token1;
    address priceProvider;
    uint104 initialToken0DensityPerLiquidityE18;
    uint104 initialToken1DensityPerLiquidityE18;
    uint104 minimalMintableLiquidity;
    bool reportSwapToPriceProvider;
    uint256 maxDriftE8;
    uint256 driftDecayPerSecondE8;
    uint24 protocolFee;
    uint24 adminFee;
    address adminFeeDestination;
    int32 curBinDistFromProvidedPriceE6;
    uint256[] nonNegativeBinDataArray;
    uint256[] negativeBinDataArray;
  }

  /// @param _factory The factory address
  constructor(address _factory) {
    factory = _factory;
  }

  /// @notice Restricts function to factory only
  modifier onlyFactory() {
    if (msg.sender != factory) revert OnlyFactory();
    _;
  }

  /// @notice Deploys a new MetricOmmPool
  /// @dev Only callable by the factory
  /// @param params The deployment parameters
  /// @return pool The deployed pool address
  function deploy(DeployParams calldata params) external onlyFactory returns (address pool) {
    pool = address(
      new MetricOmmPool{salt: params.salt}(
        params.factory,
        params.admin,
        params.token0,
        params.token1,
        params.priceProvider,
        params.initialToken0DensityPerLiquidityE18,
        params.initialToken1DensityPerLiquidityE18,
        params.minimalMintableLiquidity,
        params.reportSwapToPriceProvider,
        params.maxDriftE8,
        params.driftDecayPerSecondE8,
        params.protocolFee,
        params.adminFee,
        params.adminFeeDestination,
        params.curBinDistFromProvidedPriceE6,
        params.nonNegativeBinDataArray,
        params.negativeBinDataArray
      )
    );
  }
}

